// ConstructionParse implements the /construction/parse endpoint.
func (s *APIService) ConstructionParse(
	ctx context.Context,
	request *types.ConstructionParseRequest,
) (*types.ConstructionParseResponse, *types.Error) {
	var tx client.Transaction

	if !request.Signed {
		err := json.Unmarshal([]byte(request.Transaction), &tx)
		if err != nil {
			return nil, sdkTypes.WrapErr(sdkTypes.ErrUnableToParseIntermediateResult, err)
		}
	} else {
		var wrappedTx client.SignedTransactionWrapper
		if err := json.Unmarshal([]byte(request.Transaction), &wrappedTx); err != nil {
			return nil, sdkTypes.WrapErr(sdkTypes.ErrUnableToParseIntermediateResult, err)
		}

		var t EthTypes.Transaction
		if err := t.UnmarshalJSON(wrappedTx.SignedTransaction); err != nil {
			return nil, sdkTypes.WrapErr(sdkTypes.ErrInvalidInput, err)
		}

		tx.To = t.To().String()
		tx.Value = t.Value()
		tx.Data = t.Data()
		tx.Nonce = t.Nonce()
		tx.GasPrice = t.GasPrice()
		tx.GasLimit = t.Gas()
		tx.GasTipCap = t.GasTipCap()
		tx.GasFeeCap = t.GasFeeCap()
		tx.ChainID = t.ChainId()
		tx.Currency = wrappedTx.Currency

		msg, err := core.TransactionToMessage(&t, EthTypes.LatestSignerForChainID(t.ChainId()), nil)
		if err != nil {
			return nil, sdkTypes.WrapErr(sdkTypes.ErrUnableToParseIntermediateResult, err)
		}
		tx.From = msg.From.Hex()
	}

	value := tx.Value
	opMethod := sdkTypes.CallOpType
	fromAddress := tx.From
	toAddress := tx.To

	// ERC20 transfer
	if len(tx.Data) != 0 && hasERC20TransferData(tx.Data) {
		address, amountSent, err := parseErc20TransferData(tx.Data)
		if err != nil {
			return nil, sdkTypes.WrapErr(sdkTypes.ErrInvalidInput, err)
		}

		value = amountSent
		opMethod = sdkTypes.OpErc20Transfer
		toAddress = address.Hex()
	}

	// Contract call parsing: when a non-ERC20-transfer transaction targets a
	// supported contract method, decode the method signature and arguments
	// directly from the transaction calldata. Because these values are derived
	// from the (signed) transaction bytes rather than caller-supplied metadata,
	// downstream consumers can treat them as a verified source of truth for the
	// transaction's intent. Calldata that does not match a supported method is
	// left undecoded so no unverified values are emitted.
	//
	// Decoding here fails closed rather than failing the request: a matched-but-
	// undecodable signature (e.g. a misconfigured entry) omits the method fields
	// and logs, instead of turning /construction/parse into a 500 for otherwise
	// valid transactions. Use ValidateSupportedContractMethods at startup to catch
	// such misconfiguration loudly.
	var methodSignature string
	var methodArgs interface{}
	if opMethod == sdkTypes.CallOpType && len(tx.Data) >= methodIDLength {
		sig, matchErr := MatchMethodSignature(s.config.RosettaCfg.SupportedContractMethods, tx.Data)
		switch {
		case matchErr != nil:
			log.Printf("construction/parse: failed to match contract method signature: %v", matchErr)
		case sig != "":
			args, parseErr := ParseContractCallData(sig, tx.Data)
			if parseErr != nil {
				log.Printf("construction/parse: failed to decode calldata for %q: %v", sig, parseErr)
			} else {
				methodSignature = sig
				methodArgs = args
			}
		}
	}

	// Address validation
	from, err := client.ChecksumAddress(fromAddress)
	if err != nil {
		return nil, sdkTypes.WrapErr(sdkTypes.ErrInvalidAddress, fmt.Errorf("%s is not a valid address: %w", tx.From, err))
	}
	to, err := client.ChecksumAddress(toAddress)
	if err != nil {
		return nil, sdkTypes.WrapErr(sdkTypes.ErrInvalidAddress, fmt.Errorf("%s is not a valid address: %w", tx.To, err))
	}

	ops := []*types.Operation{
		{
			Type: opMethod,
			OperationIdentifier: &types.OperationIdentifier{
				Index: 0,
			},
			Account: &types.AccountIdentifier{
				Address: from,
			},
			Amount: &types.Amount{
				Value:    new(big.Int).Neg(value).String(),
				Currency: tx.Currency,
			},
		},
		{
			Type: opMethod,
			OperationIdentifier: &types.OperationIdentifier{
				Index: 1,
			},
			Account: &types.AccountIdentifier{
				Address: to,
			},
			Amount: &types.Amount{
				Value:    value.String(),
				Currency: tx.Currency,
			},
		},
	}

	metadata := &client.ParseMetadata{
		Nonce:           tx.Nonce,
		GasPrice:        tx.GasPrice,
		GasLimit:        tx.GasLimit,
		GasTipCap:       tx.GasTipCap,
		GasFeeCap:       tx.GasFeeCap,
		ChainID:         tx.ChainID,
		MethodSignature: methodSignature,
		MethodArgs:      methodArgs,
	}
	metaMap, err := client.MarshalJSONMap(metadata)
	if err != nil {
		return nil, sdkTypes.WrapErr(sdkTypes.ErrUnableToParseIntermediateResult, err)
	}

	var resp *types.ConstructionParseResponse
	if request.Signed {
		resp = &types.ConstructionParseResponse{
			Operations: ops,
			AccountIdentifierSigners: []*types.AccountIdentifier{
				{
					Address: fromAddress,
				},
			},
			Metadata: metaMap,
		}
	} else {
		resp = &types.ConstructionParseResponse{
			Operations:               ops,
			AccountIdentifierSigners: []*types.AccountIdentifier{},
			Metadata:                 metaMap,
		}
	}
	return resp, nil
}

// erc20TransferMethodID calculates the first 4 bytes of the method
// signature for transfer on an ERC20 contract
func erc20TransferMethodID() ([]byte, error) {
	transferFnSignature := []byte(client.TransferFnSignature)
	hash := sha3.NewLegacyKeccak256()
	if _, err := hash.Write(transferFnSignature); err != nil {
		return nil, err
	}

	return hash.Sum(nil)[:4], nil
}

func parseErc20TransferData(data []byte) (*common.Address, *big.Int, error) {
	if len(data) != client.GenericTransferBytesLength {
		return nil, nil, errors.New("incorrect length for data array")
	}

	methodID, _ := erc20TransferMethodID()
	if hexutil.Encode(data[:4]) != hexutil.Encode(methodID) {
		return nil, nil, errors.New("incorrect methodID signature")
	}

	address := common.BytesToAddress(data[5:36])
	amount := new(big.Int).SetBytes(data[37:])

	return &address, amount, nil
}

func hasERC20TransferData(data []byte) bool {
	methodID := data[:4]
	expectedMethodID, _ := erc20TransferMethodID()

	return bytes.Equal(methodID, expectedMethodID)
}


